using Hardcodet.Wpf.TaskbarNotification;
using Microsoft.Win32;
using System.Drawing;
using System.IO;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;
using ClipSync.App.Diagnostics;
using ClipSync.App.Localization;

namespace ClipSync.App.Tray;

/// <summary>
/// Owns the notification-area icon and swaps the charter tray assets
/// (Assets/Icons/tray-*.ico, generated by scripts/generate-tray-icons.py from
/// docs/design/icons/tray-*.svg) as the application state changes. The icon set follows the
/// taskbar theme (not the app theme): it is sampled at startup and re-sampled on every
/// system theme broadcast, so a light/dark taskbar flip swaps the stroke set live.
/// </summary>
internal sealed class TrayIconController : IDisposable
{
    /// <summary>SM_CXSMICON: the small-icon width the shell uses for the tray at the current DPI.</summary>
    private const int SmallIconWidthMetric = 49;

    private readonly TaskbarIcon taskbarIcon;
    private Dictionary<TrayState, Icon> stateIcons;
    private bool iconsLight;
    private bool disposed;
    private TrayState currentState = TrayState.Flow;
    private string currentToolTip;
    private DiagnosticsWindow? diagnosticsWindow;

    private TrayIconController(TaskbarIcon taskbarIcon, Dictionary<TrayState, Icon> stateIcons, bool iconsLight)
    {
        this.taskbarIcon = taskbarIcon;
        this.stateIcons = stateIcons;
        this.iconsLight = iconsLight;
        currentToolTip = taskbarIcon.ToolTipText;
        SystemEvents.UserPreferenceChanged += OnUserPreferenceChanged;
    }

    /// <summary>
    /// Charter surface map (pc-settings-preview §00): single left click opens the quick
    /// flyout, double click / menu opens the main window. Without a flyout callback the
    /// single click falls back to opening the main window.
    /// </summary>
    public static TrayIconController Create(Window mainWindow, Action exit, Action? showFlyout = null)
    {
        var menu = new ContextMenu();
        var openItem = new MenuItem { Header = Strings.Tray_Menu_Open };
        openItem.Click += (_, _) => Show(mainWindow);
        menu.Items.Add(openItem);
        var diagnosticsItem = new MenuItem { Header = Strings.Tray_Menu_Diagnostics };
        menu.Items.Add(diagnosticsItem);
        menu.Items.Add(new Separator());
        var exitItem = new MenuItem { Header = Strings.Tray_Menu_Exit };
        exitItem.Click += (_, _) => exit();
        menu.Items.Add(exitItem);

        var light = IsTaskbarLight();
        var stateIcons = LoadStateIcons(light);
        var taskbarIcon = new TaskbarIcon
        {
            ToolTipText = Strings.Tray_Tooltip_Flow,
            Icon = stateIcons[TrayState.Flow],
            ContextMenu = menu
        };
        if (showFlyout is null)
        {
            taskbarIcon.TrayLeftMouseDown += (_, _) => Show(mainWindow);
        }
        else
        {
            // Tray mouse events arrive straight from the icon's native WndProc, outside the
            // WPF dispatcher's exception handling: anything thrown here kills the process.
            taskbarIcon.TrayLeftMouseUp += (_, _) =>
            {
                try
                {
                    showFlyout();
                }
                catch (InvalidOperationException)
                {
                    LocalDiagnostics.Write("tray_flyout_failed");
                }
            };
            taskbarIcon.TrayMouseDoubleClick += (_, _) => Show(mainWindow);
        }

        var controller = new TrayIconController(taskbarIcon, stateIcons, light);
        diagnosticsItem.Click += (_, _) => controller.ShowDiagnostics();
        return controller;
    }

    /// <summary>
    /// Applies a tray state: same polyline, different stroke treatment. The optional
    /// detail is appended to the tooltip only for <see cref="TrayState.Attention"/>.
    /// </summary>
    public void SetState(TrayState state, string? attentionDetail = null)
    {
        var toolTip = state switch
        {
            TrayState.Attention => Strings.Format(
                nameof(Strings.Tray_Tooltip_AttentionFormat), attentionDetail ?? Strings.Tray_AttentionFallback),
            TrayState.Paused => Strings.Tray_Tooltip_Paused,
            TrayState.Private => Strings.Tray_Tooltip_Private,
            _ => Strings.Tray_Tooltip_Flow,
        };
        if (state == currentState && toolTip == currentToolTip)
        {
            return;
        }

        currentState = state;
        currentToolTip = toolTip;
        taskbarIcon.Icon = stateIcons[state];
        taskbarIcon.ToolTipText = toolTip;
    }

    /// <summary>
    /// Announces newly arrived remote clips. The balloon names the device and the count
    /// only — clipboard content never appears in notifications.
    /// </summary>
    public void ShowRemoteClipNotice(string deviceLabel, int count)
    {
        var message = count == 1
            ? Strings.Format(nameof(Strings.Tray_RemoteClipOneFormat), deviceLabel)
            : Strings.Format(nameof(Strings.Tray_RemoteClipManyFormat), deviceLabel, count);
        taskbarIcon.ShowBalloonTip(Strings.App_Name, message, BalloonIcon.Info);
    }

    /// <summary>
    /// States that an oversized copy stays local (charter: 超限内容明确提示，不静默截断).
    /// The size fact only — clipboard content never appears in notifications.
    /// </summary>
    public void ShowOversizeClipNotice()
    {
        taskbarIcon.ShowBalloonTip(
            Strings.App_Name,
            Strings.Tray_OversizeNotice,
            BalloonIcon.Info);
    }

    /// <summary>
    /// Warns that a device tripped the failed-auth rate limit. Names the device only — no proof
    /// material — and mirrors the persistent diagnostics entry the viewer shows.
    /// </summary>
    public void ShowAuthThrottleNotice(string deviceLabel)
    {
        taskbarIcon.ShowBalloonTip(
            Strings.App_Name,
            Strings.Format(nameof(Strings.Tray_AuthThrottleFormat), deviceLabel),
            BalloonIcon.Warning);
    }

    /// <summary>
    /// Points at the approval window a phone just summoned (it flashes in the taskbar but may
    /// sit behind whatever the user is doing). Names the candidate only — no id, no platform.
    /// </summary>
    public void ShowPairingRequestNotice(string displayName)
    {
        if (disposed)
        {
            return;
        }

        taskbarIcon.ShowBalloonTip(
            Strings.Format(nameof(Strings.Tray_PairingRequest_TitleFormat), displayName),
            Strings.Tray_PairingRequest_Body,
            BalloonIcon.Info);
    }

    /// <summary>
    /// The approval window closed unanswered after the phone's 90-second wait. Fires from
    /// the approval timeout up to 90 s after the request, so it may land during teardown.
    /// </summary>
    public void ShowPairingTimeoutNotice()
    {
        if (disposed)
        {
            return;
        }

        taskbarIcon.ShowBalloonTip(
            Strings.Tray_PairingTimeout_Title,
            Strings.Tray_PairingTimeout_Body,
            BalloonIcon.Warning);
    }

    /// <summary>Opens (or re-focuses) the read-only diagnostics viewer.</summary>
    public void ShowDiagnostics()
    {
        if (diagnosticsWindow is not null)
        {
            diagnosticsWindow.Activate();
            return;
        }

        var window = new DiagnosticsWindow();
        try
        {
            window.Show();
        }
        catch (InvalidOperationException)
        {
            // Application shutdown won the race; the viewer stays closed and nothing is retained.
            LocalDiagnostics.Write("diagnostics_show_refused");
            return;
        }

        diagnosticsWindow = window;
        window.Closed += (_, _) => diagnosticsWindow = null;
    }

    public void Dispose()
    {
        disposed = true;
        SystemEvents.UserPreferenceChanged -= OnUserPreferenceChanged;
        diagnosticsWindow?.Close();
        diagnosticsWindow = null;
        taskbarIcon.Dispose();
        foreach (var icon in stateIcons.Values)
        {
            icon.Dispose();
        }
    }

    private void OnUserPreferenceChanged(object sender, UserPreferenceChangedEventArgs e)
    {
        // Light/dark flips broadcast as General; VisualStyle covers theme-pack changes
        // (same filter as CharterThemeManager). The tray follows the taskbar theme even
        // while the app theme is pinned by a manual 外观 override — it lives in the
        // taskbar, not in our windows.
        if (e.Category is not (UserPreferenceCategory.General or UserPreferenceCategory.VisualStyle))
        {
            return;
        }

        // SystemEvents raises on its own broadcast thread; TaskbarIcon is a DispatcherObject.
        Application.Current?.Dispatcher.BeginInvoke(ReloadIconsForTaskbarTheme);
    }

    private void ReloadIconsForTaskbarTheme()
    {
        // Re-read inside the dispatched work: broadcasts can arrive in bursts, and only
        // the final taskbar theme matters. A dispose racing the dispatch is a no-op.
        var light = IsTaskbarLight();
        if (disposed || light == iconsLight)
        {
            return;
        }

        var replaced = stateIcons;
        stateIcons = LoadStateIcons(light);
        iconsLight = light;
        taskbarIcon.Icon = stateIcons[currentState];
        foreach (var icon in replaced.Values)
        {
            icon.Dispose();
        }
    }

    private static Dictionary<TrayState, Icon> LoadStateIcons(bool light)
    {
        // The taskbar theme picks the asset set: "day" strokes (t1 #1c2733) on a light
        // taskbar, "night" strokes (t1 #e3e9f0) on a dark one. This resolves the SVGs'
        // currentColor at load time.
        var theme = light ? "day" : "night";
        var size = SmallIconSize();
        return new Dictionary<TrayState, Icon>
        {
            [TrayState.Flow] = LoadIcon($"tray-flow-{theme}", size),
            [TrayState.Attention] = LoadIcon($"tray-attention-{theme}", size),
            [TrayState.Paused] = LoadIcon($"tray-paused-{theme}", size),
            [TrayState.Private] = LoadIcon($"tray-private-{theme}", size),
        };
    }

    private static Icon LoadIcon(string name, int size)
    {
        var uri = new Uri($"pack://application:,,,/Assets/Icons/{name}.ico", UriKind.Absolute);
        var resource = Application.GetResourceStream(uri)
            ?? throw new IOException($"Tray icon resource '{name}.ico' is missing.");
        using var stream = resource.Stream;
        // Picks the ICO frame nearest the shell's small-icon size, so the 16-grid
        // geometry rasterized for that size is shown instead of a scaled-down 32px frame.
        return new Icon(stream, size, size);
    }

    /// <summary>The taskbar follows the Windows theme, not the app theme; missing value means dark.</summary>
    private static bool IsTaskbarLight()
    {
        using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(
            @"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize");
        return key?.GetValue("SystemUsesLightTheme") is int value && value != 0;
    }

    private static int SmallIconSize()
    {
        var metric = NativeMethods.GetSystemMetrics(SmallIconWidthMetric);
        return metric > 0 ? metric : 16;
    }

    /// <summary>
    /// Brings the main window up from the tray (menu 打开, double click, or the single-click
    /// fallback). The same native-WndProc caveat as the flyout applies: a Show() refused
    /// during shutdown must be absorbed here or it takes the process down.
    /// </summary>
    private static void Show(Window window)
    {
        try
        {
            window.Show();
            if (window.WindowState == WindowState.Minimized)
            {
                window.WindowState = WindowState.Normal;
            }

            window.Activate();
        }
        catch (InvalidOperationException)
        {
            LocalDiagnostics.Write("tray_open_refused");
        }
    }

    private static class NativeMethods
    {
        [DllImport("user32.dll")]
        internal static extern int GetSystemMetrics(int nIndex);
    }
}
